def chain_follows_chain(chain):
    chain_dict = {}
    for a, b in chain:
        chain_dict[a] = b

    stack = [chain[0]]
    result = []

    while stack:
        current = stack[-1]
        next_item = stack.pop()

        if current in chain_dict:
            result.append(current)
        else:
            if next_item in chain_dict:
                result.append(chain_dict[next_item])
            else:
                result.append(next_item)

    return ','.join(result)

